-- Council leaders: 381 councils, sources read 2026-10-19
-- written by scripts/import-council-leaders.js --sql
\set ON_ERROR_STOP on
BEGIN;

-- name is NULL only where the council page confirms the post is vacant
CREATE TEMP TABLE leader_new (slug text PRIMARY KEY, role text NOT NULL, name text, party text, since date, since_text text, source text NOT NULL, second text, wiki text NOT NULL) ON COMMIT DROP;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.councils c JOIN leader_new l ON l.slug = c.slug;
  IF n <> 381 THEN RAISE EXCEPTION 'expected 381 councils, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils c JOIN leader_new l ON l.slug = c.slug AND c.wikipedia_url = l.wiki;
  IF n <> 381 THEN RAISE EXCEPTION 'expected 381 councils whose wikipedia_url is the source read, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils;
  IF n <> 382 THEN RAISE EXCEPTION 'expected 382 councils in all, found %', n; END IF;
END $$;

CREATE TABLE public.councils_leader_backup_20261019o AS SELECT c.slug, c.leader_name, c.leader_party, c.leader_role, c.leader_since,
  c.leader_since_text, c.leader_source_url, c.leader_checked_on, c.leader_second_source_url FROM public.councils c;

UPDATE public.councils c SET leader_role = l.role, leader_name = l.name, leader_party = l.party, leader_since = l.since,
  leader_since_text = l.since_text, leader_source_url = l.source, leader_checked_on = '2026-10-19', leader_second_source_url = l.second
  FROM leader_new l WHERE l.slug = c.slug;

-- councils with no sourced leader (gloucester): every leader field cleared
UPDATE public.councils c SET leader_role = NULL, leader_name = NULL, leader_party = NULL, leader_since = NULL, leader_since_text = NULL,
  leader_source_url = NULL, leader_checked_on = NULL, leader_second_source_url = NULL
  WHERE NOT EXISTS (SELECT 1 FROM leader_new l WHERE l.slug = c.slug);

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.councils_leader_backup_20261019o;
  IF n <> 382 THEN RAISE EXCEPTION 'expected 382 rows backed up, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils WHERE leader_source_url IS NOT NULL;
  IF n <> 381 THEN RAISE EXCEPTION 'expected 381 councils with a leader source, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils WHERE leader_source_url IS NULL AND leader_name IS NULL AND leader_party IS NULL AND leader_role IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'expected 1 councils with every leader field cleared, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils WHERE leader_source_url IS NOT NULL AND leader_name IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'expected 1 vacant posts, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils WHERE leader_since_text IS NOT NULL;
  IF n <> 2 THEN RAISE EXCEPTION 'expected 2 part dates, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils WHERE leader_checked_on = '2026-10-19';
  IF n <> 381 THEN RAISE EXCEPTION 'expected 381 councils checked on 2026-10-19, found %', n; END IF;
  SELECT count(*) INTO n FROM public.councils WHERE leader_second_source_url IS NOT NULL;
  IF n <> 12 THEN RAISE EXCEPTION 'expected 12 councils with a second source, found %', n; END IF;
END $$;

SELECT leader_role, count(*) FROM public.councils GROUP BY 1 ORDER BY 2 DESC;

COMMIT;
